DEFECTS = [
 dict(id='VB01',summary='미완료 상태로 이전 미리보기에서 생성 진입 가능',status='웹 재현·미수정',uis=['UI45','UI46','UI47','UI48'],tests=[13],expected='미리보기와 생성 시작에서 완료 상태·유효 미디어 재검증'),
 dict(id='VB02',summary='분할 길이 증가 후 원본 15초에 사용 13~21초 표시',status='웹 재현·미수정',uis=['UI43','UI44'],tests=[14],expected='분할 길이 변경 시 시작 위치 보정 또는 적용 거부, 렌더 전 구간 재검증'),
 dict(id='VB03',summary='UI41 자르기 적용 후 장소 완료 표시 유지',status='코드 확인·실행 검수 대기',uis=['UI41'],tests=[16],expected='변경된 장소의 완료 재확인; 자르기 진입은 UI41'),
 dict(id='VB04',summary='글씨체 전체 적용 시 다른 장소의 완료 표시 유지',status='코드 확인·실행 검수 대기',uis=['UI45'],tests=[16],expected='변경된 모든 장소의 완료 재확인'),
]
def defects_for_ui(ui):
    return [x for x in DEFECTS if ui in x['uis']]
def defect_ids_for_test(number):
    return ', '.join(x['id'] for x in DEFECTS if number in x['tests'])

