def apply_model(screen, screens, decisions, questions, qa, pending):
    decisions.extend(DECISIONS); questions.extend(QUESTIONS); qa['F30']=QA
    for i,(title,rows,notes,states,api) in enumerate(SCREEN_DATA,39):
        screen(f'UI{i:02}',title,'F30','현재 참여자(방장 포함) · 출시 단계 Q20',rows,notes,states,api)
    for s in screens:
        if s['id']=='UI05':
            s['features'].append('F30')
            s['rows'].append(('outline','브이로그 만들기 → UI39'))
            s['notes'].append('9f64b5e: 하단 브이로그 만들기는 방장·참여자 모두 제공. 방장의 일정 추가와 함께 표시한다. 구 PPT에는 없는 최신 변경이므로 최신 실행 캡처를 우선한다.')
    for i in range(1,len(QA)+1):
        pending[f'TC-F30-{i:02}'] = (['Q19','Q20'] if i in (4,5,6,7,8) else ['Q20','Q21'])
